    },
    {
      "id": "R4",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "1주 매수가 지수 구성 주식 전체를 보유하는 것과 유사하다는 사실이 소액 분산 투자 효과라는 판단을 뒷받침한다."
    },
    {
      "id": "R5",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "장중 실시간 거래에 필요한 가치 정보를 제공하기 위한 보완 지표로 실시간 추정 순자산가치가 제시된다."
    },
    {
      "id": "R6",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "하루 한 번 산출되는 순자산가치로는 장중 거래를 지원하기 어렵다는 한계를 실시간 추정 지표로 보완한다."
    },
    {
      "id": "R7",
      "type": "CAUSE",
      "otherName": "",
      "reason": "시장 가격이 매수·매도 수요에 의해 형성되는 작용 때문에 자산 가치와의 괴리가 발생할 수 있다."
    },
    {
      "id": "R8",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "시장 가격과 실시간 추정 순자산가치의 괴리를 수치로 나타내는 괴리율의 계산식을 정의한다."
    },
    {
      "id": "R9",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "자산 가치보다 현저히 비싸거나 싸게 거래된다는 내용을 투자자의 거래 위험이라는 말로 다시 풀어 쓴다."
    },
    {
      "id": "R10",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "본질 가치와 동떨어진 가격에 거래할 위험에 대한 대응으로 괴리율을 축소하는 차익 거래가 제시된다."
    },
    {
      "id": "R11",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "지속적인 매수·매도 호가 제시는 투자자의 원활한 거래를 돕기 위해 마련된 수단이다."
    },
    {
      "id": "R12",
      "type": "PROCESS",
      "otherName": "",
      "reason": "기초 자산 바스켓을 매수한 다음 그 매수물을 자산 운용사에 제공하는 설정 절차의 순서이다."
    },
    {
      "id": "R13",
      "type": "PROCESS",
      "otherName": "",
      "reason": "기초 자산 바스켓을 제공한 뒤 그 대가로 ETF 증권을 발행받는 설정 절차의 다음 단계이다."
    },
    {
      "id": "R14",
      "type": "PROCESS",
      "otherName": "",
      "reason": "ETF 증권을 매수한 다음 그 증권을 자산 운용사에 반납하는 환매 절차의 순서이다."
    },
    {
      "id": "R15",
      "type": "PROCESS",
      "otherName": "",
      "reason": "ETF 증권을 반납한 뒤 상응하는 기초 자산 바스켓을 지급받는 환매 절차의 다음 단계이다."
    },
    {
      "id": "R16",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "설정과 환매는 제공하는 자산과 지급받는 자산이라는 같은 기준에서 교환 방향이 서로 다르다."
    },
    {
      "id": "R17",
      "type": "PROCESS",
      "otherName": "",
      "reason": "설정 단계에서 발행받은 ETF 증권을 바탕으로 시장 매도와 차익 실현이라는 후속 단계가 진행된다."
    },
    {
      "id": "R18",
      "type": "PROCESS",
      "otherName": "",
      "reason": "환매 단계에서 지급받은 기초 자산 바스켓을 바탕으로 시장 매도와 차익 실현이라는 후속 단계가 진행된다."
    },
    {
      "id": "R19",
      "type": "CONDITION",
      "otherName": "",
      "reason": "괴리율이 양수인지 음수인지에 따라 참여 절차와 매도 대상이 갈리므로 조건·분기 관계이다."
    },
    {
      "id": "R20",
      "type": "CAUSE",
      "otherName": "",
      "reason": "반복적인 차익 거래가 시장 가격을 본질 가치에 근접시키고 괴리율을 축소하는 실제 작용을 한다."
    },
    {
      "id": "R21",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "패시브형과 액티브형은 상관 계수 기준과 운용 목표라는 공통 기준에서 서로 다른 특성을 보인다."
    },
    {
      "id": "R22",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "상관 계수를 0.9 이상으로 유지하는 설계는 기초 지수 수익률을 유사하게 구현하기 위한 수단이다."
    },
    {
      "id": "R23",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "지수 변동을 확대해 추종하는 레버리지 구조를 설명한 뒤 같은 구조의 손실 확대 위험을 한계로 제시한다."
    },
    {
      "id": "R24",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "매일 평가액을 새 원금으로 삼는 계산 원리가 지수 회복에도 원금 손실이 남는다는 설명을 뒷받침한다."
    },
    {
      "id": "R25",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "지수가 회복되어도 평가액이 9,000원에 그치는 수치 사례가 레버리지형 ETF의 손실 원리를 구체적으로 보여 준다."
    },
    {
      "id": "R26",
      "type": "PROCESS",
      "otherName": "",
      "reason": "첫날 하락으로 산출된 평가액 6,000원을 바탕으로 다음 날 상승률을 반영하는 계산 단계가 이어진다."
    },
    {
      "id": "R27",
      "type": "CAUSE",
      "otherName": "",
      "reason": "주가 상승 전에 권리를 판매한 행위가 이후 가격 상승에 따른 수익 실현을 제한한다."
    },
    {
      "id": "R28",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 커버드콜형 ETF 안에서 상승 수익의 제한이라는 단점과 주기적 현금 수익이라는 장점을 함께 제시한다."
    },
    {
      "id": "R29",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유형별 손실 위험과 수익 제한이 있다는 사실을 근거로 여러 요인을 종합하여 상품을 선택해야 한다는 당위를 도출한다."
    },
    {
      "id": "R30",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유형마다 수익 목표와 운용 기준이 다르다는 사실이 상품 선택 시 운용 방식 등을 고려해야 한다는 주장을 뒷받침한다."
    },
    {
      "id": "R31",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "ETF의 기초 지수 추종 특성을 추종 정도와 운용 목표가 다른 두 유형으로 나누어 더 자세히 설명한다."
